/// Parses a semantic version string in `major.minor.patch` form.
///
/// Returns `None` if the input is not exactly three dot-separated non-negative
/// integers.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_semver("1.2.3"), Some((1, 2, 3)));
/// assert_eq!(parse_semver("0.0.1"), Some((0, 0, 1)));
/// assert_eq!(parse_semver("1.2"), None);
/// assert_eq!(parse_semver("1.2.3.4"), None);
/// assert_eq!(parse_semver("a.b.c"), None);
/// ```
fn parse_semver(version: &str) -> Option<(u32, u32, u32)> {
    let mut parts = version.split('.');

    let major = parts.next()?.parse::<u32>().ok()?;
    let minor = parts.next()?.parse::<u32>().ok()?;
    let patch = parts.next()?.parse::<u32>().ok()?;

    if parts.next().is_some() {
        None
    } else {
        Some((major, minor, patch))
    }
}
```

